"functions": [
  {
    "name": "getAccount",
    "type": "function",
    "description": "Retrieve information about a single cloud file account. Returns <var>undefined</var>, if the requested account does not exist.",
    "allowedContexts": ["content"],
    "async": "callback",
    "parameters": [
      {
        "name": "accountId",
        "type": "string",
        "description": "Unique identifier of the account."
      },
      {
        "type": "function",
        "name": "callback",
        "optional": true,
        "parameters": [
          {
            "optional": true,
            "$ref": "CloudFileAccount"
          }
        ]
      }
    ]
  },
  {
    "name": "getAllAccounts",
    "type": "function",
    "description": "Retrieve all cloud file accounts for the current add-on.",
    "allowedContexts": ["content"],
    "async": "callback",
    "parameters": [
      {
        "type": "function",
        "name": "callback",
        "optional": true,
        "parameters": [
          {
            "type": "array",
            "items": {
              "$ref": "CloudFileAccount"
            }
          }
        ]
      }
    ]
